 await s.releaseOrder(actor,{orderId:o.id,correlationId:'release-1'});await s.releaseOrder(actor,{orderId:o.id,correlationId:'release-1'});await s.recover(actor);await s.recover(actor);assert.equal(sink.receipts().length,1);
