test('commit: failed pre-commit attempt does not count and retry succeeds',async()=>{
 const journal=createJournal();journal.failNext({key:'north:k',phase:'before'});const s=createService({journal});
 await assert.rejects(s.createOrder(actor,order()),/storage/);assert.equal(s.countOrders(actor),0);
