test('commit: lost acknowledgement preserves committed identity on retry',async()=>{
 const journal=createJournal(),sink=createSink();journal.failNext({key:'north:k',phase:'after'});const s=createService({journal,sink});
 await assert.rejects(s.createOrder(actor,order()),/storage/);assert.equal(s.countOrders(actor),1);
