 journal.failNext({key:'north:two',phase:'after'});await assert.rejects(first.createOrder(actor,order('two')));
 const second=createService({journal,sink});await second.recover(actor);await second.recover(actor);
 assert.equal(second.countOrders(actor),2);assert.equal(sink.receipts().length,2);assert.equal(new Set(sink.receipts().map(x=>x.orderId)).size,2);
