test('independence: another key progresses while one persistence is blocked',async()=>{
 let release,entered;const inside=new Promise(r=>entered=r);const blocked=new Promise(r=>release=r);
 const journal=createJournal({beforeCommit:async o=>{if(o.key==='slow'){entered();await blocked;}}});const s=createService({journal});
 const slow=s.createOrder(actor,order('slow'));await inside;
 const fast=await Promise.race([s.createOrder(actor,order('fast')),new Promise((_,reject)=>{const t=setTimeout(()=>reject(Error('different-key blocked')),1000);t.unref();})]);
 assert.equal(fast.key,'fast');release();await slow;assert.equal(s.countOrders(actor),2);
});
test('isolation: tenant/key identity and denied mutations remain independent',async()=>{
