test('replay: provider success followed by missing local marker remains exactly once',async()=>{
 const journal=createJournal(),sink=createSink();const original=journal.appendEvent;let failed=false;
 journal.appendEvent=event=>{if(event.type==='fulfillment.sent'&&!failed){failed=true;throw Error('local receipt persistence failed');}return original(event);};
