export async function readTree(root,{skip=[]}={}){
 const files={};let bytes=0;
 async function walk(relative=''){
  for(const entry of await readdir(path.join(root,relative),{withFileTypes:true})){
   if(skip.includes(entry.name))continue;
   const name=relative?relative+'/'+entry.name:entry.name;const full=path.join(root,name);const stat=await lstat(full);
   if(stat.isSymbolicLink())throw Error('Symlink is not accepted: '+name);
   if(stat.isDirectory())await walk(name);else if(stat.isFile()){
    if(stat.size>1048576||Object.keys(files).length>=256)throw Error('Artifact bounds exceeded');
    bytes+=stat.size;if(bytes>8*1024*1024)throw Error('Artifact byte bound');files[name]=await readFile(full,'utf8');
   }else throw Error('Unsupported artifact type');
  }
 }
 await walk();return files;
}
export async function writeTree(root,files){
