  if(path.isAbsolute(name)||name.split('/').some(x=>!x||x==='.'||x==='..')||name.includes('\\'))throw Error('Unsafe path');
  const dest=path.join(root,name);await mkdir(path.dirname(dest),{recursive:true,mode:0o700});await writeFile(dest,text,{flag:'wx',mode:0o600});
