 const prompt=prompts[id]+' Read TASK.md, ACCEPTANCE.md and context/00-index.md. Deliver all artifacts specified there. The task materials are complete; make bounded documented assumptions instead of requesting additional input.';
 files['TASK.md']='# Task\n\n'+prompt+'\n';files['ACCEPTANCE.md']=acceptanceText(id);
 const referenceFiles={...files,...await readTree(path.join(HERE,'reference',id))};
