export function billingRoutes(service) {
  return async ({method, path, actor, query}) => {
    if (method === 'GET' && path === '/invoices') return {status: 200, body: await service.exportInvoices(actor, query)};
    return null;
  };
}

export function fulfillmentRoutes(service) {
  return async ({method, path, actor, body}) => {
    if (method === 'POST' && path === '/fulfillment/run') return {status: 200, body: {receipts: await service.recover(actor)}};
    const match = /^\/orders\/(ord-[0-9]+)\/(hold|release)$/.exec(path);
    if (method === 'POST' && match) {
      const operation = match[2] === 'hold' ? service.holdOrder : service.releaseOrder;
      return {status: 200, body: await operation(actor, {...body, orderId: match[1]})};
    }
    return null;
  };
}

export function orderRoutes(service) {
  return async ({method, path, actor, body}) => {
    if (method === 'POST' && path === '/orders') return {status: 201, body: await service.createOrder(actor, body)};
    if (method === 'GET' && path === '/orders') return {status: 200, body: {items: service.listOrders(actor)}};
    const match = /^\/orders\/(ord-[0-9]+)$/.exec(path);
    if (method === 'GET' && match) return {status: 200, body: service.getOrder(actor, match[1])};
    return null;
  };
}

